#include <stdbool.h>
#include <stddef.h>
bool percentage(int part, int total, double *result)
{
    if (result == NULL || total <= 0 || part < 0 || part > total) return false;
    *result = 100.0 * (double)part / (double)total;
    return true;
}
int main(void) { double value = 0.0; if (percentage(3, 4, &value)) { /* use value */ } return 0; }

#include <errno.h>
#include <limits.h>
#include <stdbool.h>
#include <stdlib.h>
bool parse_quantity(const char *text, int *out)
{
    char *end = NULL; long value;
    if (text == NULL || out == NULL || *text == '\0') return false;
    errno = 0; value = strtol(text, &end, 10);
    if (end == text || *end != '\0' || errno == ERANGE || value < 0 || value > INT_MAX) return false;
    *out = (int)value; return true;
}
int main(void) { int n = 0; return parse_quantity("25", &n) ? 0 : 1; }
